// The prompt path's ratio-2 chain: tf_ds_compress2_kernel (grid-stride over G*C, here one block per group, the pair
// sums staged through shared memory as bf16 exactly as the unfused launch round-trips them through global memory)
// followed by tf_ds_rms_norm_kernel's arithmetic (torch's reduce order, the block's lane count passed as blockDim.x,
// the same `factor` the unfused launch computes). One block per group g, grid.x = G. `factor` is rows/(rows*D) as
// float, computed by the caller exactly as Exact.rmsNorm does.
// The pair pass over ITEMS channels a thread, keeping each channel's bf16 result: the norm's output is the same
// flattened `lane + i * threads` index, so the store reads the register value instead of shared srow (srow still feeds
// the reduction, whose four-channel mapping differs).
// `raw_kv`/`raw_score` (null when the caller scatters them itself): this block's two raw rows go to the ring at
// their modular positions, which is the scatter launch the prompt source step used to run for them. Only rows at or
// past `raw_first` are written, the window the scatter covers (the last raw_rows rows of a chunk).
template<int ITEMS>
__device__ __forceinline__ void tf_ds_compress2_norm_items(const float* kv, const float* score, const __nv_bfloat16* w,
                                                           __nv_bfloat16* out, __nv_bfloat16* srow, long long ldo,
                                                           int D, float factor, float eps, float* raw_kv,
                                                           float* raw_score, int ring_len, long long raw_pos0,
                                                           int raw_first) {
    const long long g = blockIdx.x;
    const int lane = threadIdx.x + blockDim.x * threadIdx.y;
    const int threads = blockDim.x * blockDim.y;
    const int slot0 = raw_kv && (2 * g) >= raw_first ? (int)((raw_pos0 + (2 * g - raw_first)) % ring_len) : -1;
    const int slot1 = raw_kv && (2 * g + 1) >= raw_first ? (int)((raw_pos0 + (2 * g + 1 - raw_first)) % ring_len) : -1;
    __nv_bfloat16 held[ITEMS];
    #pragma unroll
    for (int i = 0; i < ITEMS; ++i) {
        const int c = lane + i * threads;
        if (c < D) {
            const float s0 = score[(g * 2) * D + c];
            const float s1 = score[(g * 2 + 1) * D + c];
            const float k0 = kv[(g * 2) * D + c];
            const float k1 = kv[(g * 2 + 1) * D + c];
            held[i] = __float2bfloat16_rn(tf_ds_compress2_pair(s0, s1, k0, k1));
            srow[c] = held[i];
            if (slot0 >= 0) {
                raw_kv[(long long)slot0 * D + c] = k0;
                raw_score[(long long)slot0 * D + c] = s0;
            }
            if (slot1 >= 0) {
                raw_kv[(long long)slot1 * D + c] = k1;
                raw_score[(long long)slot1 * D + c] = s1;
            }
        }
    }
    __syncthreads();
    tf_ds_torch_rmsnorm_row_held<ITEMS>(srow, w, out + g * ldo, D, factor, eps, held);
}

// grid.x = G complete pairs plus (n_rows odd) one more block that writes only the trailing row's raw-ring slot: the
// trailing row has no pair, so it produces no latent, and the source step needs its raw bytes in the ring.
extern "C" __global__ void tf_ds_compress2_norm_kernel(const float* kv, const float* score,
                                                       const __nv_bfloat16* w, __nv_bfloat16* out,
                                                       long long ldo, int G, int D, float factor, float eps, int pdl,
                                                       float* raw_kv, float* raw_score, int ring_len,
                                                       long long raw_pos0, int raw_first, int n_rows) {
    pdl_enter(pdl);
    const long long g = blockIdx.x;
    __shared__ __nv_bfloat16 srow[2048];   // D <= 2048
    const int threads = blockDim.x * blockDim.y;
    if (2 * g + 1 >= n_rows) {
        const long long j = 2 * g;
        if (raw_kv && j >= raw_first && j < n_rows) {
            const int slot = (int)((raw_pos0 + (j - raw_first)) % ring_len);
            for (int c = threadIdx.x + blockDim.x * threadIdx.y; c < D; c += threads) {
                raw_kv[(long long)slot * D + c] = kv[j * D + c];
                raw_score[(long long)slot * D + c] = score[j * D + c];
            }
        }
        return;
    }
    // the launcher's block is min(D, target) lanes over a whole number of channels a thread: 1, 2, 4, 8 or 16 items
    if (threads > 0 && threads <= D && (D % threads) == 0) {
        switch (D / threads) {
            case 1: tf_ds_compress2_norm_items<1>(kv, score, w, out, srow, ldo, D, factor, eps, raw_kv, raw_score, ring_len, raw_pos0, raw_first); return;
            case 2: tf_ds_compress2_norm_items<2>(kv, score, w, out, srow, ldo, D, factor, eps, raw_kv, raw_score, ring_len, raw_pos0, raw_first); return;
            case 4: tf_ds_compress2_norm_items<4>(kv, score, w, out, srow, ldo, D, factor, eps, raw_kv, raw_score, ring_len, raw_pos0, raw_first); return;
            case 8: tf_ds_compress2_norm_items<8>(kv, score, w, out, srow, ldo, D, factor, eps, raw_kv, raw_score, ring_len, raw_pos0, raw_first); return;
            case 16: tf_ds_compress2_norm_items<16>(kv, score, w, out, srow, ldo, D, factor, eps, raw_kv, raw_score, ring_len, raw_pos0, raw_first); return;
            default: break;
        }
    }
    // any other geometry: the pair pass, then the norm's own store over srow
    const int slot0 = raw_kv && (2 * g) >= raw_first ? (int)((raw_pos0 + (2 * g - raw_first)) % ring_len) : -1;
    const int slot1 = raw_kv && (2 * g + 1) >= raw_first ? (int)((raw_pos0 + (2 * g + 1 - raw_first)) % ring_len) : -1;
    for (int c = threadIdx.x + blockDim.x * threadIdx.y; c < D; c += threads) {
        const float s0 = score[((long long)g * 2) * D + c];
        const float s1 = score[((long long)g * 2 + 1) * D + c];
        const float k0 = kv[((long long)g * 2) * D + c];
        const float k1 = kv[((long long)g * 2 + 1) * D + c];
        srow[c] = __float2bfloat16_rn(tf_ds_compress2_pair(s0, s1, k0, k1));
        if (slot0 >= 0) {
            raw_kv[(long long)slot0 * D + c] = k0;
            raw_score[(long long)slot0 * D + c] = s0;
        }
        if (slot1 >= 0) {
            raw_kv[(long long)slot1 * D + c] = k1;
            raw_score[(long long)slot1 * D + c] = s1;
        }
    }
    __syncthreads();
    tf_ds_torch_rmsnorm_row(srow, w, out + (long long)g * ldo, D, factor, eps);
}

// Each warp resolves both partners before reading any ring data. Use the first
// matching current row, including when that row belongs to another block.
__device__ __forceinline__ int2 tf_ds_compress2_partners(const long long* slots, int rows,
                                                        long long own, long long q0, long long q1) {
    if (rows == 1) return make_int2(own == q0 ? 0 : -1, own == q1 ? 0 : -1);
    int2 found = make_int2(-1, -1);
    for (int first = 0; first < rows; first += 32) {
        const int r = first + (threadIdx.x & 31);
        const long long slot = r < rows ? slots[r] : -1;
        const unsigned m0 = __ballot_sync(0xffffffffu, r < rows && slot == q0);
        const unsigned m1 = __ballot_sync(0xffffffffu, r < rows && slot == q1);
        if (found.x < 0 && m0) found.x = first + __ffs(m0) - 1;
        if (found.y < 0 && m1) found.y = first + __ffs(m1) - 1;
        if (found.x >= 0 && found.y >= 0) break;
    }
    return found;
}

template<int D>
__device__ __forceinline__ void tf_ds_compress2_decode(float value, const __nv_bfloat16* w, __nv_bfloat16* dst, float eps) {
    const int tid = threadIdx.x;
    const float x = __bfloat162float(__float2bfloat16_rn(value));
    // Keep the rounded channel in a register for the final multiply. At width 512
    // the kit first reduces four adjacent channels per logical lane.
    __shared__ float row[D == 512 ? 512 : 1];
    if (D == 512) {
        row[tid] = x;
        __syncthreads();
    }
    __shared__ float warp_sum[4];
    if (tid < 128) {
        float sum;
        if (D == 512) {
            const int base = tid * 4;
            sum = tf_ds_kit_squares4(row[base], row[base + 1], row[base + 2], row[base + 3]);
        } else {
            sum = __fmul_rn(x, x);
        }
        sum = tf_ds_kit_warp_sum(sum);
        if ((tid & 31) == 0) warp_sum[tid >> 5] = sum;
    }
    __syncthreads();
    const float sum = __fadd_rn(__fadd_rn(warp_sum[0], warp_sum[2]), __fadd_rn(warp_sum[1], warp_sum[3]));
    const float inv = tf_ds_kit_inverse_rms<D>(sum, eps);
    const float y = __fmul_rn(x, inv);
    dst[tid] = __float2bfloat16_rn(__fmul_rn(__bfloat162float(w[tid]), y));
}

// Decode ratio-2 scatter, pair compression and kit RMSNorm. Launch exactly D threads per row, one channel a thread.
// The width is a compile-time parameter with one kernel exported per served width (decodeOk: 128 or 512), so neither
// kernel carries the other's code or its static shared allocation: at the served decode rows a dedicated 128-wide
// kernel measures 1.30/1.54/1.54/1.78 us (R = 1/7/32/48) against 1.50/1.73/1.73/1.95 for the shared one, and the
// 512-wide form 1.69/1.92/1.95/2.20 against 1.73/1.95/1.99/2.22. The 128-wide block is exactly the reduction's 128
// lanes, so it needs no `tid < 128` guard (that guard alone costs ~0.12 us: it puts the warp-sum store and the
// shuffles behind a runtime branch ptxas cannot fold away) and no shared `row`.
template<int D>
__device__ __forceinline__ void tf_ds_compress2x_norm_body(const float* ckv, long long ckv_ld,
                                                          const float* cgate, long long cgate_ld,
                                                          const long long* rslot, float* ring_kv,
                                                          float* ring_score, const long long* gi, long long src_rows,
                                                          __nv_bfloat16 wv, __nv_bfloat16* out, long long ldo,
                                                          int G, float eps, unsigned* invalid) {
    const int g = blockIdx.x;
    const int tid = threadIdx.x;
    const long long own = rslot[g];
    // The partner slots are read before the current row: ptxas then issues both 64-bit slot loads ahead of the pair
    // loads, which hides their latency behind the scatter and the ballot scan (the other order measures 1.46 against
    // 1.32 us at R = 1, width 128, with otherwise identical SASS).
    const long long q0 = gi[2 * g], q1 = gi[2 * g + 1];
    const float own_kv = ckv[g * ckv_ld + tid], own_score = cgate[g * cgate_ld + tid];
    ring_kv[own * D + tid] = own_kv;
    ring_score[own * D + tid] = own_score;
    const int2 pr = tf_ds_compress2_partners(rslot, G, own, q0, q1);
    const bool ok0 = q0 >= 0 && q0 < src_rows, ok1 = q1 >= 0 && q1 < src_rows;
    if ((!ok0 || !ok1) && tid == 0 && invalid) atomicExch(invalid, 1u);
    float kv[2], score[2];
    #pragma unroll
    for (int i = 0; i < 2; ++i) {
        const bool ok = i == 0 ? ok0 : ok1;
        const int row = i == 0 ? pr.x : pr.y;
        const long long q = i == 0 ? q0 : q1;
        if (!ok) {
            kv[i] = score[i] = 0.f;
        } else if (row == g) {
            kv[i] = own_kv;
            score[i] = own_score;
        } else if (row >= 0) {
            kv[i] = ckv[row * ckv_ld + tid];
            score[i] = cgate[row * cgate_ld + tid];
        } else {
            kv[i] = ring_kv[q * D + tid];
            score[i] = ring_score[q * D + tid];
        }
    }
    const float value = tf_ds_compress2_pair(score[0], score[1], kv[0], kv[1]);
    const float x = __bfloat162float(__float2bfloat16_rn(value));
    // At width 512 the kit first reduces four adjacent channels per logical lane, so the block stages the rounded row.
    __shared__ float row[D == 512 ? 512 : 1];
    if (D == 512) {
        row[tid] = x;
        __syncthreads();
    }
    __shared__ float warp_sum[4];
    if (D == 512) {
        if (tid < 128) {
            const int base = tid * 4;
            float sum = tf_ds_kit_squares4(row[base], row[base + 1], row[base + 2], row[base + 3]);
            sum = tf_ds_kit_warp_sum(sum);
            if ((tid & 31) == 0) warp_sum[tid >> 5] = sum;
        }
    } else {
        float sum = __fmul_rn(x, x);
        sum = tf_ds_kit_warp_sum(sum);
        if ((tid & 31) == 0) warp_sum[tid >> 5] = sum;
    }
    __syncthreads();
    const float total = __fadd_rn(__fadd_rn(warp_sum[0], warp_sum[2]), __fadd_rn(warp_sum[1], warp_sum[3]));
    const float inv = tf_ds_kit_inverse_rms<D>(total, eps);
    const float y = __fmul_rn(x, inv);
    out[g * ldo + tid] = __float2bfloat16_rn(__fmul_rn(__bfloat162float(wv), y));
}

#define TF_DS_COMPRESS2X_NORM_KERNEL(name, D)                                                                          \
    extern "C" __global__ void __launch_bounds__(D) name(const float* ckv, long long ckv_ld, const float* cgate,        \
        long long cgate_ld, const long long* rslot, float* ring_kv, float* ring_score, const long long* gi,             \
        long long src_rows, const __nv_bfloat16* w, __nv_bfloat16* out, long long ldo, int G, int D_, float eps,         \
        unsigned* invalid, int pdl) {                                                                                   \
        (void)D_;                                                                                                       \
        if (pdl) {                                                                                                      \
            /* TF_DS_PDL: the successor may be scheduled now; the comp_norm weight is a fixed model weight (no writer \
               in the round), so it is read here, before the wait for the predecessor's bytes. */                        \
            pdl_launch(1);                                                                                              \
            const __nv_bfloat16 wv = w[threadIdx.x];                                                                    \
            pdl_wait(1);                                                                                                \
            tf_ds_compress2x_norm_body<D>(ckv, ckv_ld, cgate, cgate_ld, rslot, ring_kv, ring_score, gi, src_rows, wv,  \
                                          out, ldo, G, eps, invalid);                                                   \
        } else {                                                                                                        \
            tf_ds_compress2x_norm_body<D>(ckv, ckv_ld, cgate, cgate_ld, rslot, ring_kv, ring_score, gi, src_rows,       \
                                          w[threadIdx.x], out, ldo, G, eps, invalid);                                   \
        }                                                                                                               \
    }

TF_DS_COMPRESS2X_NORM_KERNEL(tf_ds_compress2x_norm128_kernel, 128)
TF_DS_COMPRESS2X_NORM_KERNEL(tf_ds_compress2x_norm512_kernel, 512)

