//! TF_DS_FUSED_COMPRESS2_NORM (off by default): the ratio-2 compressor chain and the RMSNorm after it in ONE launch.
//!
//! Prompt follows Exact.compress2 and Exact.rmsNorm, including bf16 staging and the row-dependent lane count.
//! Decode combines the 0127 scatter/gather/compress2 with the pinned kit RMSNorm for the recorded widths.
//! TF_DS_FUSED_COMPRESS2 alone keeps its separate kit norm. Other widths retain the existing decode path.
const std = @import("std");

pub const env_name: [:0]const u8 = "TF_DS_FUSED_COMPRESS2_NORM";

/// The switch's value: unset, "" or "0" off; "1" on; anything else is a refusal to start (the message is on stderr).
pub fn parse(text: ?[]const u8) ?bool {
    const t = text orelse return false;
    if (t.len == 0 or std.mem.eql(u8, t, "0")) return false;
    if (std.mem.eql(u8, t, "1")) return true;
    std.debug.print("{s}: expected 1 or 0\n", .{env_name});
    return null;
}

pub fn fromText(text: ?[]const u8) error{BadCompress2Norm}!bool {
    return parse(text) orelse error.BadCompress2Norm;
}

fn isPow2(n: usize) bool {
    return n > 0 and (n & (n - 1)) == 0;
}

/// Prompt uses the vectorized torch norm. Decode additionally requires a matching kit specialization.
pub fn fuseOk(fused: bool, rows: usize, d: usize) bool {
    return fused and rows > 0 and isPow2(d) and d >= 128 and d <= 2048;
}

/// Prompt grid width (`grid.x`) for `n_rows` input rows: `n_rows / 2` pair blocks plus one trailing raw-ring block when
/// `n_rows` is odd.
pub fn gridRows(n_rows: usize) usize {
    return (n_rows + 1) / 2;
}

pub fn decodeOk(fused: bool, rows: usize, d: usize) bool {
    return fused and rows > 0 and (d == 128 or d == 512);
}

test "decode fusion uses recorded four-warp kit widths" {
    for ([_]usize{ 128, 512 }) |d| try std.testing.expect(decodeOk(true, 1, d));
    for ([_]usize{ 256, 1024, 2048 }) |d| try std.testing.expect(!decodeOk(true, 1, d));
}

// -- host reference --------------------------------------------------------------------------------------------------

/// Round-to-nearest-even f32 -> bf16 -> f32 (the rounding the kernels apply at every bf16 store).
pub fn bf16Round(x: f32) f32 {
    if (std.math.isNan(x)) return x;
    const b: u32 = @bitCast(x);
    return @bitCast((b + 0x7FFF + ((b >> 16) & 1)) & 0xFFFF0000);
}

/// The pair's softmax-weighted sum (tf_ds_compress2_kernel's arithmetic), the raw fp32 value.
pub fn pairSum(kv0: f32, kv1: f32, s0: f32, s1: f32) f32 {
    var m: f32 = -3.402823466e+38; // numeric_limits<float>::lowest()
    if (s0 > m) m = s0;
    if (s1 > m) m = s1;
    var sum: f32 = 0;
    sum += @exp(s0 - m);
    sum += @exp(s1 - m);
    const p0 = @exp(s0 - m) / sum;
    const p1 = @exp(s1 - m) / sum;
    const y0 = kv0 * p0;
    const y1 = kv1 * p1;
    return ((0.0 + y0) + (0.0 + y1)) + 0.0 + 0.0;
}

/// The pair sum as the kernels store it: bf16-rounded.
pub fn pairSumBf16(kv0: f32, kv1: f32, s0: f32, s1: f32) f32 {
    return bf16Round(pairSum(kv0, kv1, s0, s1));
}

/// The torch rms_norm lane count (exact.zig's rmsLanes; replicated here so this module stands alone — the test below
/// asserts the two agree).
pub fn rmsLanes(d: usize, rows: usize) usize {
    const dim0 = d / 4;
    const d0 = if (dim0 < 512) lastPow2(dim0) else 512;
    const d1 = if (rows < 512) lastPow2(rows) else 512;
    const bw: usize = @min(d0, 32);
    const bh: usize = @min(d1, 512 / bw);
    return @min(d0, 512 / bh);
}

fn lastPow2(n: usize) usize {
    return if (n == 0) 0 else @as(usize, 1) << @intCast(std.math.log2_int(usize, n));
}

/// The pair pass's thread count (exact.compress2Norm's block: rmsLanes lanes over `groups` y lanes).
pub fn pairThreads(d: usize, rows: usize) usize {
    const lanes = rmsLanes(d, rows);
    const target: usize = if (rows <= 32) 512 else if (rows <= 128) 256 else 128;
    return @max(1, @min(d, target) / lanes) * lanes;
}

/// The channels one thread produces and then stores: tf_ds_compress2_norm_kernel's held-values specialization is
/// unrolled per item count (1, 2, 4, 8, 16); any other count takes the generic path that rereads srow.
pub fn pairItems(d: usize, rows: usize) usize {
    return d / pairThreads(d, rows);
}

/// The norm of one bf16-valued row, torch's lane structure (per-lane 4-wide vector accumulators combined in order,
/// the L>32 fold, the shuffle down), returning bf16-valued f32. `factor` is torch's rows/(rows*D) as f32. Not
/// bit-identical to the kernel (rsqrtf vs 1/@sqrt); used for the property tests, not for bitwise checks.
pub fn rmsNormRef(x: []const f32, w: []const f32, out: []f32, lanes: usize, factor: f32, eps: f32) void {
    const d = x.len;
    const l = lanes;
    var part: [512]f32 = @splat(0);
    var lane: usize = 0;
    while (lane < l) : (lane += 1) {
        var a0: f32 = 0;
        var a1: f32 = 0;
        var a2: f32 = 0;
        var a3: f32 = 0;
        var idx = lane;
        while (idx * 4 + 3 < d) : (idx += l) {
            a0 += x[idx * 4 + 0] * x[idx * 4 + 0];
            a1 += x[idx * 4 + 1] * x[idx * 4 + 1];
            a2 += x[idx * 4 + 2] * x[idx * 4 + 2];
            a3 += x[idx * 4 + 3] * x[idx * 4 + 3];
        }
        part[lane] = ((a0 + a1) + a2) + a3;
    }
    var dim_x = l;
    if (l > 32) {
        var offset = l / 2;
        while (offset >= 32) : (offset >>= 1) {
            var lane2: usize = 0;
            while (lane2 < offset) : (lane2 += 1) {
                if (lane2 + offset < l) part[lane2] = part[lane2] + part[lane2 + offset];
            }
        }
        dim_x = 32;
    }
    var offset = dim_x / 2;
    while (offset > 0) : (offset >>= 1) {
        var lane2: usize = 0;
        while (lane2 < dim_x) : (lane2 += 1) {
            if (lane2 + offset < dim_x) part[lane2] = part[lane2] + part[lane2 + offset];
        }
    }
    const r = 1.0 / @sqrt(part[0] * factor + eps);
    var j: usize = 0;
    while (j < d) : (j += 1) out[j] = bf16Round(w[j] * (x[j] * r));
}

// -- tests -----------------------------------------------------------------------------------------------------------

const expectEqual = std.testing.expectEqual;
const exact = @import("exact.zig");

test "the switch parses its forms and nothing else" {
    try expectEqual(false, parse(null).?);
    try expectEqual(false, parse("").?);
    try expectEqual(false, parse("0").?);
    try expectEqual(true, parse("1").?);
    try expectEqual(@as(?bool, null), parse("2"));
    try expectEqual(@as(?bool, null), parse("yes"));
    try expectEqual(@as(?bool, null), parse("01"));
    try std.testing.expectEqual(@as(bool, true), try fromText("1"));
    try std.testing.expectError(error.BadCompress2Norm, fromText("2"));
}

test "fuseOk takes pow2 channel counts in [128, 2048] and any nonzero rows" {
    try std.testing.expect(fuseOk(true, 1, 512));
    try std.testing.expect(fuseOk(true, 16, 128));
    try std.testing.expect(fuseOk(true, 2048, 2048));
    try std.testing.expect(!fuseOk(true, 0, 512));
    try std.testing.expect(!fuseOk(false, 16, 512));
    try std.testing.expect(!fuseOk(true, 16, 96)); // not pow2
    try std.testing.expect(!fuseOk(true, 16, 64)); // too narrow for the torch norm's vectorization
    try std.testing.expect(!fuseOk(true, 16, 4096));
    try std.testing.expect(!fuseOk(true, 16, 500)); // not pow2
}

test "rmsLanes matches exact.zig's" {
    for ([_]usize{ 128, 256, 512, 1024, 2048 }) |d| {
        for ([_]usize{ 1, 2, 3, 4, 5, 8, 9, 16, 17, 33, 512, 2048 }) |rows| {
            try expectEqual(exact.rmsLanes(d, rows), rmsLanes(d, rows));
        }
    }
}

test "pairItems: every served geometry is a held-values specialization power of two" {
    for ([_]usize{ 128, 256, 512, 1024, 2048 }) |d| {
        for ([_]usize{ 1, 2, 7, 16, 32, 33, 64, 128, 129, 512, 1024, 2048 }) |rows| {
            const threads = pairThreads(d, rows);
            try std.testing.expect(threads > 0 and threads <= d);
            try std.testing.expectEqual(@as(usize, 0), d % threads); // whole channels a thread
            const items = pairItems(d, rows);
            try std.testing.expect(items == 1 or items == 2 or items == 4 or items == 8 or items == 16);
        }
    }
}

test "pairSum: the softmax pair, bf16 rounding at the store" {
    // s0 == s1: the softmax splits 0.5/0.5; the pair sum is the mean of the kv values
    const v = pairSum(2.0, 4.0, 1.0, 1.0);
    try std.testing.expectApproxEqAbs(@as(f32, 3.0), v, 1e-6);
    try expectEqual(@as(f32, 3.0), pairSumBf16(2.0, 4.0, 1.0, 1.0));
    // one score far above the other: the pair sum is that side's kv (to bf16)
    try expectEqual(bf16Round(4.0), pairSumBf16(2.0, 4.0, -100.0, 100.0));
    // a tie at the -inf floor: both weights equal
    const v2 = pairSum(2.0, 6.0, -3.4e38, -3.4e38);
    try std.testing.expectApproxEqAbs(@as(f32, 4.0), v2, 1e-3);
}

test "bf16Round rounds to nearest even at the 16-bit boundary" {
    try expectEqual(@as(f32, 1.0), bf16Round(1.0));
    try expectEqual(@as(f32, 1.0), bf16Round(1.00390625)); // halfway between 1.0 and 1.0078125 -> ties to even (1.0)
    try expectEqual(@as(f32, 1.015625), bf16Round(1.01171875)); // halfway -> ties to even (1.015625)
    try expectEqual(@as(f32, 0.0), bf16Round(0.0));
    try expectEqual(@as(f32, -0.0), bf16Round(-0.0));
}

test "rmsNormRef: a constant row normalizes to w * sign (x * rinv)" {
    // x = c (all ones): sum = d * c^2; rinv = rsqrt(c^2 + eps); out = bf16(w * c * rinv)
    var x: [512]f32 = @splat(2.0);
    var w: [512]f32 = @splat(1.5);
    var out: [512]f32 = undefined;
    rmsNormRef(&x, &w, &out, 32, 1.0 / 512.0, 1e-20);
    const expect_v = bf16Round(1.5 * (2.0 / @sqrt(4.0 + 1e-20)));
    for (out) |v| try expectEqual(expect_v, v);
}

//! TF_DS_IDX_FUSED (off by default): the indexer's candidate pool in one launch - the block maxima
//! (tf_ds_block_max_kernel), the top-k over them (tf_ds_topk_indices_kernel's selection) and the pool's mask / block
//! list (tf_ds_pool_pick_kernel), one block per row. Pure: no cuda import; the launcher is Ops.idxFused and the call
//! sites are round.zig's candidate-source arm (the decode rows) and prompt.zig's chunk path (the pooled source layer).
//!
//! The fused path selects a cutoff on chip and compacts the selected columns in ascending order. It writes only the
//! mask (the prompt arm) or the block list (decode): the global block maxima and the selected-column list had no reader
//! on the fused path, so the kernel keeps both on chip (the unfused launches still write them, and the host reference
//! below still describes them). Past max_nbk the call sites use the unfused launches. A malformed switch refuses startup.
const std = @import("std");

pub const env_name: [:0]const u8 = "TF_DS_IDX_FUSED";

/// The switch's value: unset, "" or "0" off; "1" on; anything else is a refusal to start (the message is on stderr).
pub fn parse(text: ?[]const u8) ?bool {
    const t = text orelse return false;
    if (t.len == 0 or std.mem.eql(u8, t, "0")) return false;
    if (std.mem.eql(u8, t, "1")) return true;
    std.debug.print("{s}: expected 1 or 0\n", .{env_name});
    return null;
}

pub fn fromText(text: ?[]const u8) error{BadIdxFused}!bool {
    return parse(text) orelse error.BadIdxFused;
}

/// Each of the two float4 loads must be aligned for every row, including a score view.
pub fn candMask8Ok(score: u64, stride: usize, bsize: usize) bool {
    return bsize == 8 and score % 16 == 0 and stride % 4 == 0;
}

test "eight-score candidate mask requires aligned rows" {
    try std.testing.expect(candMask8Ok(0x1000, 2048, 8));
    try std.testing.expect(!candMask8Ok(0x1004, 2048, 8));
    try std.testing.expect(!candMask8Ok(0x1000, 2049, 8));
    try std.testing.expect(!candMask8Ok(0x1000, 2048, 4));
}

/// The selection's k bound (the pool's top blocks: candidate_blocks at both call sites, 2048 on this checkpoint).
pub const max_k = 2048;
/// The maxima's block count past which the fused launch keeps one block a row for work the unfused launches spread
/// over a 2D grid: the fused path covers the pool's regime (nbk > candidate_blocks) up to 16384 blocks (131,072
/// columns at the served block size, a 262,144-token bucket at ratio 2); past it the unfused sequence runs. The bound
/// is the GPU's opt-in dynamic shared memory (101,376 bytes here: 25,344 blocks of one fp32 maximum) rounded down to
/// the served power of two, not the radix shortcut: that one skips the columns' two constant high bytes and would
/// still hold to 65,536 blocks, where a column's inverted id leaves 0xFFFE in them.
pub const max_nbk = 16384;

/// Rows at or below this use the small-row form: the maxima over the pool's own 2D grid (block_max), then the selection
/// from those global maxima in one CTA a row (tf_ds_idx_pick_kernel), because a single CTA a row leaves most of the GPU
/// idle at one to seven rows. Above it the one-launch fused form runs. Both produce the same block list.
pub const small_rows = 7;
/// The block count from which the small-row form pays: at 8192 blocks (65,536 columns; `max_nbk` is 16,384) the 2D
/// grid's parallel score read wins at both one and seven rows (10.5 vs 12.1 µs, 11.8 vs 12.4 µs); at 2048 and 4096
/// blocks the second launch and the selection's staging cost more than the parallel read saves (5.8 vs 5.6, 8.7 vs 8.5 µs).
pub const small_nbk = 6144;

/// Whether the fused launch supports this configuration. The call sites fall back to the unfused sequence when it
/// does not. k > nbk (the selection's own bound) and nbk <= 0 refuse; `width` must agree with `bsize`.
pub fn fuseOk(fused: bool, rows: usize, width: usize, bsize: usize, nbk: usize, k: usize) bool {
    return fused and rows > 0 and width > 0 and width <= std.math.maxInt(c_int) and bsize >= 1 and bsize <= std.math.maxInt(c_int) and nbk == 1 + (width - 1) / bsize and nbk >= 1 and nbk <= max_nbk and k >= 1 and k <= max_k and k <= nbk;
}

// -- host reference -------------------------------------------------------------------------------------------------
//
// The kernel's arithmetic on the host, written to the same spec (used by the tests below). fp32 with IEEE semantics;
// the selection is keyed on the same 64-bit key and is computed by sorting (the kernel's radix select is the same
// total order, which is what the tests check the fused arm against semantically, not algorithmically).

const ninf: f32 = -std.math.inf(f32);

/// The key tf_ds_score_key makes: the score's bits (-0 as +0) ordered as signed integers, above the inverted column.
pub fn scoreKey(x: f32, j: usize) u64 {
    var bits: u32 = @bitCast(x);
    if (bits == 0x80000000) bits = 0; // score + 0.0
    const sb: i32 = @bitCast(bits);
    const ordered: i32 = if (sb < 0) sb ^ 0x7FFFFFFF else sb;
    const key = (@as(u64, @bitCast(@as(i64, ordered))) << 32) | @as(u64, 0xFFFFFFFF - @as(u64, @intCast(j)));
    return key ^ 0x8000000000000000;
}

/// The block maxima (tf_ds_block_max_kernel's rule): an amax over each block of `bsize` scores (a NaN wins, the NaN is
/// quiet 0x7fc00000), the row's newest block (floor((vis - 1) / bsize), floor division on negatives) +inf.
pub fn blockMaxima(score: []const f32, width: usize, bsize: usize, vis: i64, out: []f32) void {
    std.debug.assert(score.len >= width and out.len >= (width + bsize - 1) / bsize);
    const nb = (width + bsize - 1) / bsize;
    const t = vis - 1;
    const last: i64 = if (t >= 0) @divFloor(t, @as(i64, @intCast(bsize))) else -@divFloor(-t + @as(i64, @intCast(bsize)) - 1, @as(i64, @intCast(bsize)));
    for (0..nb) |b| {
        var m: f32 = ninf;
        var nan = false;
        for (0..bsize) |j| {
            if (b * bsize + j >= width) break;
            const x = score[b * bsize + j];
            if (x != x) nan = true else if (x > m) m = x;
        }
        var v: f32 = if (nan) @bitCast(@as(u32, 0x7fc00000)) else m;
        if (@as(i64, @intCast(b)) == last) v = std.math.inf(f32);
        out[b] = v;
    }
}

/// The top-k of the maxima by the key order (ties to the lower column; k <= nb), ascending columns, a column at or
/// past `every` as -1. Independent of the kernel's radix select (a sort, the same total order).
pub fn topCols(bmax: []const f32, every: i64, k: usize, out: []i64) void {
    std.debug.assert(bmax.len >= k and out.len >= k and k >= 1 and bmax.len <= max_nbk);
    var keys: [max_nbk]u64 = undefined;
    var cols: [max_nbk]usize = undefined;
    for (0..bmax.len) |i| {
        keys[i] = scoreKey(bmax[i], i);
        cols[i] = i;
    }
    // selection sort of the k largest keys (descending); the keys are unique, so this is stable on columns
    for (0..k) |n| {
        var best = n;
        for (n + 1..bmax.len) |i| {
            if (keys[i] > keys[best]) best = i;
        }
        std.mem.swap(u64, &keys[n], &keys[best]);
        std.mem.swap(usize, &cols[n], &cols[best]);

        std.mem.swap(usize, &cols[n], &cols[best]);
    }
    // the k largest, columns ascending (the kernel's bitonic sort of the same set)
    std.mem.sort(usize, cols[0..k], {}, std.sort.asc(usize));
    for (0..k) |n| {
        const c: i64 = @intCast(cols[n]);
        out[n] = if (c < every) c else -1;
    }
}

/// The pool pick (tf_ds_pool_pick_kernel's rule): `mask` (if given) is zeroed and each picked block whose maximum is
/// above -inf sets its byte; `cblk` (if given) lists the block, or -1 when its maximum is not above -inf (a NaN
/// maximum is not above -inf either). A negative column is not picked (the unfused launch reads bmax before the row
/// there, unreachable today: every is every_vis).
pub fn poolPick(bmax: []const f32, idx: []const i64, mask: ?[]u8, cblk: ?[]i32) void {
    if (mask) |m| @memset(m, 0);
    for (idx, 0..) |c, j| {
        const ok = c >= 0 and bmax[@intCast(c)] > ninf;
        if (mask) |m| {
            if (ok) m[@intCast(c)] = 1;
        }
        if (cblk) |cb| cb[j] = if (ok) @intCast(c) else -1;
    }
}

