const expectEqual = std.testing.expectEqual;

test "the switch parses its forms and nothing else" {
    try expectEqual(false, parse(null).?);
    try expectEqual(false, parse("").?);
    try expectEqual(false, parse("0").?);
    try expectEqual(true, parse("1").?);
    try expectEqual(@as(?bool, null), parse("2"));
    try expectEqual(@as(?bool, null), parse("yes"));
    try expectEqual(@as(?bool, null), parse("01"));
    try std.testing.expectEqual(@as(bool, true), try fromText("1"));
    try std.testing.expectError(error.BadIdxFused, fromText("2"));
}

test "fuseOk takes the pool's bounds" {
    try std.testing.expect(fuseOk(true, 16, 16392, 8, 2049, 2048)); // the smallest pooled case
    try std.testing.expect(fuseOk(true, 1, 64, 8, 8, 4));
    try std.testing.expect(fuseOk(true, 2048, 131072, 8, 16384, 2048)); // the nbk cap, inclusive
    try std.testing.expect(!fuseOk(true, 16, 131080, 8, 16385, 2048)); // past the cap
    try std.testing.expect(fuseOk(true, 2048, 65536, 8, 8192, 2048)); // the old cap is inside the new one
    try std.testing.expect(!fuseOk(false, 16, 16392, 8, 2049, 2048));
    try std.testing.expect(!fuseOk(true, 0, 16392, 8, 2049, 2048));
    try std.testing.expect(!fuseOk(true, 16, 16392, 8, 2050, 2048)); // nbk disagrees with width/bsize
    try std.testing.expect(!fuseOk(true, 16, 16392, 8, 2049, 3000)); // k past the 2048 cap
    try std.testing.expect(!fuseOk(true, 16, 16392, 8, 2049, 2050)); // k past nbk
    try std.testing.expect(!fuseOk(true, 16, 16392, 0, 16392, 4));
    try std.testing.expect(fuseOk(true, 16, 100, 8, 13, 13)); // k == nbk is fine
    try std.testing.expect(!fuseOk(true, 16, 100, 8, 13, 14)); // k > nbk is not
}

test "scoreKey matches the -0/+0 rule and orders scores like signed integers" {
    // +0.0 and -0.0 get the same key modulo the column; a larger score always wins a smaller column
    const a = scoreKey(5.0, 0);
    const b = scoreKey(-5.0, 0);
    try std.testing.expect(a > b);
    const key_neg_zero = scoreKey(-0.0, 3);
    const key_pos_zero = scoreKey(0.0, 3);
    try expectEqual(key_pos_zero, key_neg_zero); // the -0 to +0 rule
    // an inverted column: a tie breaks to the lower column
    try std.testing.expect(scoreKey(1.0, 0) > scoreKey(1.0, 1));
    // NaN above +inf, as the bit order makes it
    try std.testing.expect(scoreKey(@bitCast(@as(u32, 0x7fc00000)), 1) > scoreKey(std.math.inf(f32), 1));
    // -inf floor: the smallest key class
    try std.testing.expect(scoreKey(0.0, 0) > scoreKey(-std.math.inf(f32), 0));
}

test "blockMaxima: NaN wins, the newest block is pinned, short blocks are padded -inf" {
    var s = [_]f32{ 1, 2, 3, @as(f32, @bitCast(@as(u32, 0x7fc00000))), -std.math.inf(f32), 4, 5, 6, 7 };
    var bmax: [3]f32 = undefined;
    blockMaxima(&s, 9, 4, 100, &bmax); // vis past the row: nothing pinned (100's newest block is 24)
    try expectEqual(@as(u32, 0x7fc00000), @as(u32, @bitCast(bmax[0]))); // block 0 holds the NaN: it wins
    try expectEqual(@as(f32, 6), bmax[1]); // islands: idx 4..7 = -inf, 4, 5, 6
    try expectEqual(@as(f32, 7), bmax[2]); // the short last block (idx 8), padded with -inf
    // the newest block pinned to +inf whatever its scores
    blockMaxima(&s, 9, 4, 7, &bmax); // vis = 7: the newest key is 6: block 1 pinned
    try expectEqual(std.math.inf(f32), bmax[1]);
    try expectEqual(@as(u32, 0x7fc00000), @as(u32, @bitCast(bmax[0])));
    // vis at or below 0: t < 0, floor division pins nothing (a negative block index)
    blockMaxima(&s, 9, 4, 0, &bmax);
    try expectEqual(@as(f32, 6), bmax[1]);
}

test "topCols picks the k largest by key, ties to the lower block, every masks the tail" {
    const bmax = [_]f32{ 1, 2, 2, -std.math.inf(f32), 9, 9, 0, 7 };
    var out: [3]i64 = undefined;
    topCols(&bmax, 100, 3, &out);
    try expectEqual([_]i64{ 4, 5, 7 }, out); // 9, 9, 7 (ties between the two 9s: the lower column first)
    // every = 5: columns at or past 5 become -1
    topCols(&bmax, 5, 3, &out);
    try expectEqual([_]i64{ 4, -1, -1 }, out);
    // -inf columns rank last (they are still selected when k > the count of finite maxima)
    const flat = [_]f32{ -std.math.inf(f32), -std.math.inf(f32) };
    var o2: [2]i64 = undefined;
    topCols(&flat, 100, 2, &o2);
    try expectEqual([_]i64{ 0, 1 }, o2);
}

test "poolPick zeroes the mask, sets picked blocks above -inf, lists -1 otherwise" {
    const bmax = [_]f32{ 5, -std.math.inf(f32), @bitCast(@as(u32, 0x7fc00000)) };
    const idx = [_]i64{ 0, 1, 2 };
    var mask = [_]u8{ 9, 9, 9 };
    var cblk = [_]i32{ 99, 99, 99 };
    poolPick(&bmax, &idx, &mask, &cblk);
    try expectEqual([_]u8{ 1, 0, 0 }, mask); // only block 0 is above -inf; the NaN and -inf blocks are not picked
    try expectEqual([_]i32{ 0, -1, -1 }, cblk);
    // a negative column (an every-masked selection) is not picked
    const idx2 = [_]i64{ -1, 0 };
    var cblk2 = [_]i32{ 99, 99 };
    poolPick(&bmax, &idx2, &mask, &cblk2);
    try expectEqual([_]i32{ -1, 0 }, cblk2);
}

test "key negative-column rule: a column at or past every is -1 in the list and not in the pool" {
    // end-to-end through the host reference: an every below some selected column
    const bmax = [_]f32{ 3, 7, 8, 1 };
    var out: [2]i64 = undefined;
    topCols(&bmax, 2, 2, &out); // selects blocks 2 and 1; ascending columns; block 2 >= every -> -1
    try expectEqual([_]i64{ 1, -1 }, out);
    var mask = [_]u8{ 9, 9, 9, 9 };
    var cblk = [_]i32{ 99, 99 };
    poolPick(&bmax, &out, &mask, &cblk);
    try expectEqual([_]u8{ 0, 1, 0, 0 }, mask); // only block 1 lands
    try expectEqual([_]i32{ 1, -1 }, cblk);
}

fn shardRound(e: *const Engine, rd: *Round, rows: Rows, kv: *shard_ops.KvShard) !void {
    const R = rows.ids.len;
    if (e.ring) |r| if (r.rowsOpen()) return error.ShardRingOrder;
    if (!rd.rcur.done() or rd.ss_q_out) return error.ShardRingOrder;
    rd.rcur.reset();
    rd.fetch_key = null; // (TF_DS_KV_FETCH_REUSE: a round's first fetch layer always fetches)
    var owners: [max_rows]u32 = undefined;
    for (0..R) |i| owners[i] = try rows.ownerOf(i, kv.sh);
    const view: shard_ring.View = .{ .owners = owners[0..R] };
    const d = try shard_ring.decide(.{
        .view = view,
        .mode = kv.mode,
        .cost = kv.cost,
        .sizes = ringSizes(e),
        .decode_rows = tri.decode_rows,
        .ring = kv.use_ring and rd.rlist != 0,
        .fit_fetch = rd.fit_fetch,
        .fit_owner = rd.fit_owner,
    });
    rd.smode = d.mode;
    rd.sring = d.ring;
    switch (d.mode) {
        .fetch => kv.stats.fetch_rounds += 1,
        .owner => kv.stats.owner_rounds += 1,
        .off, .auto => unreachable,
    }
    if (kv.mode == .auto) {
        if (d.mode == .fetch) kv.stats.auto_fetch += 1 else kv.stats.auto_owner += 1;
    }
    const ls = (try shard_ring.roundLists(d, view, kv.sh.rank)) orelse return;
    kv.stats.ring_rounds += 1;
    kv.stats.sent_rows += if (d.mode == .fetch) ls.get(.fetch, .send).n else ls.get(.q, .send).n + ls.get(.out, .send).n;
    var dev: [shard_ring.Lists.words]i32 = undefined;
    ls.encode(&dev);
    try prompt.upload(e, rd.rlist, &dev, shard_ring.Lists.bytes);
}

/// A listed row's bytes in each decode exchange (auto's cost model): every pick of a fetched row, a row's queries, a
/// row's rotated wo_a inputs.
fn ringSizes(e: *const Engine) shard_ring.Sizes {
    const c = e.c;
    const l0 = e.w.layers[0];
    var wo_k: usize = 0;
    for (l0.wo_a[0..l0.groups]) |wo| wo_k += wo.k;
    return .{ .fetch_row = c.index_topk * (c.head_dim / 2 + c.head_dim / 16), .q_row = e.heads() * c.head_dim * 2, .out_row = wo_k * 2 };
}

/// The layer's RoPE table rows (model.py _cs: the compressed table for a compressed layer).
fn ropeOf(e: *const Engine, lay: weights.Layer) prompt.Rope {
    return if (lay.ratio != 0) e.compressed else e.plain;
}

/// TF_DS_CHECK_INVALID: the compressor's out-of-range-partner flag, read back after a ratio-2 chain (the switch's own
/// synchronizing read: diagnostic only) and logged once. A set flag means a group's partner row was outside the ring,
/// where every compressor path substitutes a zero row - the output is wrong and nothing else says so.
var invalid_warned: bool = false;

fn checkInvalid(e: *const Engine, ch: *const Chunk, li: usize) !void {
    if (!e.ops.check_invalid or invalid_warned) return;
    var flag: u32 = 0;
    try e.d.check(e.d.api.cuMemcpyDtoH_v2(&flag, ch.invalid, 4), "cuMemcpyDtoH");
    if (flag != 0) {
        invalid_warned = true;
        std.log.err("dsv41: TF_DS_CHECK_INVALID: layer {d}: a ratio-2 compressor partner row was out of range (a zero row was used: the layer's output is wrong)", .{li});
    }
}

/// The compressor's chain (a compressed layer): the RMSNorm alone at ratio 1; at ratio 2 the scatter of the rows
/// into the group's raw slots, the memset of ch.invalid, the double gather back, compress2's
/// weighted sum to bf16, the RMSNorm — or, at ratio 2 with TF_DS_FUSED_COMPRESS2=1 (set alike on both ranks), the
/// scatter+gather+compress2 as one fused kernel launch (exact.compress2x; the memset stays out, its flag is dead).
/// One copy of the launches, run on `t`/`s`: the unforked path passes the main stream, the forked
/// (TF_DS_COMPRESS_SIDE) path the chain's own (every launch rides `s`: the kit's through the stream-carrying Tri
/// `t`, the ops and the memset through `s` directly, so the event ordering is total). Both paths take the same
/// fused-or-unfused choice (rd.fused_compress2), so the side-stream path gets it too.
fn compressorChain(e: *const Engine, rd: *const Round, ch: *const Chunk, t: tri.Tri, s: cuda.Stream, caches: *const Caches, li: usize, ratio: usize) !void {
    const lay = e.w.layers[li];
    const c = e.c;
    const hd = c.head_dim;
    const R = rd.r;
    if (ratio == 1) {
        try tri_basic.rmsnorm(t, rd.ckv, hd, lay.comp_norm, rd.lat, hd, c.eps, R, hd);
        return;
    }
    if (ratio == 2) {
        if (fused_trace.compressArm(e.ops.compress2_norm, false, R, hd) == .compress2x_norm) {
            // Same stream and ring writes as compress2x. Stage the bf16 pair sum on chip for the kit norm.
            try e.exact.compress2xNorm(s, rd.ckv, hd, rd.cgate, hd, rd.g(.rslot), caches.raw_kv[li], caches.raw_score[li], rd.g(.gi), caches.slots * raw_rows, lay.comp_norm, rd.lat, hd, R, hd, c.eps, ch.invalid);
            try checkInvalid(e, ch, li);
            return;
        }
        if (fused_trace.enabled()) fused_trace.note(.compress_unfused, R, hd, e.ops.pdl);
        if (rd.fused_compress2) {
            // TF_DS_FUSED_COMPRESS2: the scatter of the rows into the raw slots, the pair's rows back and compress2's
            // weighted sum in one launch (LDs in elements of the buffer's dtype; the memset stays out — ch.invalid's
            // flag is dead on this path: written by gatherRows, read nowhere, tree-wide; the kernel still writes 1 to
            // it were a partner out of range, like gatherRows). LDs here: ckv/cgate rows hd floats, the ring's rows hd
            // floats (src_rows rows), rd.lat2 rows hd bf16 elements.
            try e.exact.compress2x(s, rd.ckv, hd, rd.cgate, hd, rd.g(.rslot), caches.raw_kv[li], caches.raw_score[li], rd.g(.gi), caches.slots * raw_rows, rd.lat2, hd, R, hd, ch.invalid);
        } else {
            // rk[rslot] = kv, rs[rslot] = score; the group's two rows back (rk[gi], rs[gi]); the pair's softmax-
            // weighted sum to bf16 (torch's ops: exact.compress2's bytes), then the RMSNorm (Triton's)
            try e.ops.scatterRows(s, rd.ckv, hd * 4, rd.g(.rslot), caches.raw_kv[li], hd * 4, hd * 4, R);
            try e.ops.scatterRows(s, rd.cgate, hd * 4, rd.g(.rslot), caches.raw_score[li], hd * 4, hd * 4, R);
            try e.d.check(e.d.api.cuMemsetD8Async(ch.invalid, 0, 4, s.handle), "cuMemsetD8Async");
            try e.ops.gatherRows(s, caches.raw_kv[li], caches.slots * raw_rows, rd.g(.gi), rd.kvg, hd * 4, 2 * R, ch.invalid);
            try e.ops.gatherRows(s, caches.raw_score[li], caches.slots * raw_rows, rd.g(.gi), rd.sg, hd * 4, 2 * R, ch.invalid);
            try e.exact.compress2(s, rd.kvg, rd.sg, rd.lat2, R, hd);
        }
        try tri_basic.rmsnorm(t, rd.lat2, hd, lay.comp_norm, rd.lat, hd, c.eps, R, hd);
        try checkInvalid(e, ch, li);
        return;
    }
    return notPorted(@src());
}

