/// scatter's in-kernel assumption). The flag is written by the unfused gatherRows path and by 0127's and 0197's
/// compressors; the fused chains do not clear it, so a set flag also latches. Diagnostic only: no kernel changes, and an
/// unset switch costs nothing (no read, no sync). Read at load on every rank.
pub const check_invalid_env = "TF_DS_CHECK_INVALID";

/// The series' switches' parse ("1" or "on"; unset, "0", "off", "" or anything else: off).
pub fn onValue(v: ?[]const u8) bool {
    const s = v orelse return false;
    return std.mem.eql(u8, s, "1") or std.mem.eql(u8, s, "on");
}

/// TF_DS_SPEC_SAMPLE's parse (the series' switches: "1" or "on"; unset, "0", "off", "" or anything else: off), and the
/// one combination refused: TF_DS_T26_KEYED_DRAFT on as ops reads it (exactly "1") with this one. Both put Gumbel noise
/// on the drafter's logits with different keys (T26 the sampler's own, so a draft lands only when it equals the target's
/// draw; this one an independent draft key, which the accept rule needs), so one pass cannot run both.
pub fn specSample(v: ?[]const u8, keyed: ?[]const u8) !bool {
    const on = onValue(v);
    if (on and isOne(keyed)) return error.SpecAndKeyedDraft;
    return on;
}

/// The message both ranks log when they refuse the pair (native.explain gives it to rank 0's start too).
pub const spec_keyed_why = "TF_DS_SPEC_SAMPLE and TF_DS_T26_KEYED_DRAFT=1 cannot run together (both put keyed noise on the drafter's logits, with different keys): set TF_DS_T26_KEYED_DRAFT=0 (any value but 1, or unset) on both ranks to run TF_DS_SPEC_SAMPLE, or unset TF_DS_SPEC_SAMPLE";

/// TF_DS_SPEC_SAMPLE: tf_ds_spec_clean_kernel's blocks a row (its grid.x), so a row's normaliser partials are
/// 2 * spec_parts floats after its clean scores.
pub const spec_parts = 16;

fn envSpan(name: [:0]const u8) ?[]const u8 {
    return if (std.c.getenv(name)) |p| std.mem.span(p) else null;
}

