/// The three images (cuda.kernels.torch_pointwise, torch_movement and dsv41_ops, or the fatbins' bytes).
pub fn load(d: *const cuda.Driver, pointwise: []const u8, movement: []const u8, family: []const u8) !Ops {
    var pw = try cuda.Module.load(d, pointwise);
    errdefer pw.unload();
    var mv = try cuda.Module.load(d, movement);
    errdefer mv.unload();
    var fm = try cuda.Module.load(d, family);
    errdefer fm.unload();
    const prune = try expert_prune.fromEnv();
    const fused_route = try fusedRoute(envSpan("TF_DS_FUSED_ROUTE"));
    const spec = specSample(envSpan(spec_env), envSpan(keyed_env)) catch |err| {
        std.log.err("dsv41: {s}", .{spec_keyed_why});
        return err;
    };
    const idx_fused_on = try idx_fused.fromText(envSpan(idx_fused.env_name));
    const check_invalid = onValue(envSpan(check_invalid_env));
    const compress2_norm_on = try compress2_norm.fromText(envSpan(compress2_norm.env_name));
    const rope_store_on = try rope_store.fromText(envSpan(rope_store.env_name));
    const conf_pack_on = try conf_pack.fromText(envSpan(conf_pack.env_name));
    const topk_merge_on = try topk_merge.fromText(envSpan(topk_merge.env_name));
    const pdl = onValue(envSpan(pdl_env));
    const topk_fast = onValue(envSpan(topk_fast_env));
    const o: Ops = .{
        .pointwise = pw,
        .movement = mv,
        .family = fm,
        .to_f32 = try pw.function("tf_bf16_to_f32_kernel"),
        .f16_to_f32 = try fm.function("tf_ds_f16_to_f32_kernel"),
        .add2_bf16 = try fm.function("tf_ds_add2_bf16_kernel"),
        .topk_i64 = try fm.function("tf_ds_topk_i64_kernel"),
        .topk_indices = try fm.function(switch (fused_trace.topkIndicesArm(idx_fused_on, false)) {
            .topk_indices_cut => "tf_ds_topk_indices_cut_kernel",
            .topk_indices => "tf_ds_topk_indices_kernel",
            .topk_indices_fast => "tf_ds_topk_indices_fast_kernel",
            else => unreachable,
        }),
        .topk_indices_fast = try fm.function("tf_ds_topk_indices_fast_kernel"), // TF_DS_TOPK_FAST (0182): launched only under it
        .scatter = try fm.function("tf_ds_scatter_rows_kernel"),
        .cand_fast = try fm.function("tf_ds_cand_fast_kernel"),
        .cand_fast8 = if (idx_fused_on) try fm.function("tf_ds_cand_fast8_kernel") else null,
        .iota_vis = try fm.function("tf_ds_iota_vis_kernel"),
        .l2_prefetch = try fm.function("tf_ds_l2_prefetch_kernel"),
        .block_max = try fm.function("tf_ds_block_max_kernel"),
        .pool_pick = try fm.function("tf_ds_pool_pick_kernel"),
        .apply_pool = try fm.function("tf_ds_apply_pool_kernel"),
        .to_bf16 = try pw.function("tf_f32_to_bf16_kernel"),
        .strided = try mv.function("tf_strided_copy_kernel"),
        .gather = try mv.function("tf_gather_rows_kernel"),
        .copy16 = try fm.function("tf_ds_copy_rows16_kernel"),
        .argmax_rows = try fm.function("tf_ds_argmax_rows_kernel"),
        .argmax_pair = try fm.function("tf_ds_argmax_pair_kernel"),
        .argmax_reduce = try fm.function("tf_ds_argmax_reduce_kernel"),
        .accept_chain = try fm.function("tf_ds_accept_chain_kernel"),
        .gpu_clock = try fm.function("tf_ds_clock_kernel"),
        .prune = prune,
        .fused_route = fused_route,
        .prune_six_fn = if (fused_route and prune != null) try fm.function("tf_ds_prune_six_kernel") else null,
        .prune_fn = if (prune != null) try fm.function("tf_ds_expert_prune_kernel") else null,
        .idx_fused = idx_fused_on,
        .idx_fused_fn = if (idx_fused_on) try fm.function("tf_ds_idx_fused_kernel") else null,
        .idx_pick_fn = if (idx_fused_on) try fm.function("tf_ds_idx_pick_kernel") else null,
        .compress2_norm = compress2_norm_on,
        .rope_store = rope_store_on,
        .conf_pack_fn = if (conf_pack_on) try fm.function("tf_ds_conf_pack_kernel") else null,
        .check_invalid = check_invalid,
        .dead_rows = try fm.function("tf_ds_dead_rows_kernel"),
        .hot_track = try fm.function("tf_ds_hot_track_kernel"),
        .keyed_noise = if (envOn(keyed_env) or spec) try fm.function("tf_ds_keyed_noise_kernel") else null,
        .spec_clean = if (spec) try fm.function("tf_ds_spec_clean_kernel") else null,
        .gather_cols = if (spec) try fm.function("tf_ds_gather_cols_kernel") else null,
        .spec = spec,
        .pdl = pdl,
        .topk_fast = topk_fast,
        .draw_rows = if (envOn(draw_env)) try fm.function("tf_ds_draw_rows_kernel") else null,
        .topk_merge = topk_merge_on,
        .topk_select_fn = if (topk_merge_on) try fm.function("tf_ds_topk_select_kernel") else null,
        .topk_merge_fn = if (topk_merge_on) try fm.function("tf_ds_topk_merge_kernel") else null,
        .draw_topk_fn = if (topk_merge_on) try fm.function("tf_ds_draw_rows_topk_kernel") else null,
        .lora_add = if (loraOn()) try fm.function("tf_ds_add_bf16_kernel") else null,
    };
    // the fused pool's maxima are dynamic shared memory: past 48 KiB each kernel opts in (max_nbk blocks of fp32)
    if (o.idx_fused_fn) |f| try f.allowDynamicShared(@intCast(idx_fused.max_nbk * @sizeOf(f32)));
    if (o.idx_pick_fn) |f| try f.allowDynamicShared(@intCast(idx_fused.max_nbk * @sizeOf(f32)));
    return o;
}

pub fn unload(o: *Ops) void {
    o.pointwise.unload();
    o.movement.unload();
    o.family.unload();
    o.* = undefined;
}

fn go(o: *const Ops, f: cuda.Function, s: cuda.Stream, grid: usize, block: u32, args: *cuda.Args) !void {
    try cuda.launch.launch(f, .{ .grid = .{ .x = @intCast(grid) }, .block = .{ .x = block }, .pdl = o.pdl }, s, args);
}

/// `.float()` of `count` bf16 values (exact).
pub fn toF32(o: *const Ops, s: cuda.Stream, in: u64, out: u64, count: usize) !void {
    if (count == 0) return;
    var a: cuda.Args = .{};
    a.add(in);
    a.add(out);
    a.add(@as(u64, count));
    a.add(@as(c_int, @intFromBool(o.pdl)));
    try go(o, o.to_f32, s, blocks(count, 256), 256, &a);
}

/// `.float()` of `count` fp16 values (exact).
pub fn f16ToF32(o: *const Ops, s: cuda.Stream, in: u64, out: u64, count: usize) !void {
    if (count == 0) return;
    var a: cuda.Args = .{};
    a.add(in);
    a.add(out);
    a.add(@as(u64, count));
    a.add(@as(c_int, @intFromBool(o.pdl)));
    try go(o, o.f16_to_f32, s, blocks(count, 256), 256, &a);
}

//! The served forward's torch arithmetic at torch's own rounding points (zig/kernels/cuda/dsv41_torch.cu), byte-equal to
//! the served build's torch ops on GB10 (tools/dsv41-zig/rec/zrec_torchlab.py): ops.rms_norm with its mean in torch's
//! reduction order, _compress's ratio-2 softmax and weighted sum, ops.rope_'s complex multiply, the indexer's bf16
//! head weights and the DSpark taps' mean over the streams.
const std = @import("std");
const cuda = @import("cuda");
const ops = @import("ops.zig");
const compress2_norm = @import("compress2_norm.zig");
const fused_trace = @import("fused_trace.zig");
const rope_store = @import("rope_store.zig");

/// launch_shape.h's tf_launch_blocks: a block a `threads` elements, at most 65535.
fn blocks(count: usize, threads: usize) u32 {
    return @intCast(@min((count + threads - 1) / threads, 65535));
}

fn lastPow2(n: usize) usize {
    return if (n == 0) 0 else @as(usize, 1) << @intCast(std.math.log2_int(usize, n));
}

/// Reduce.cuh's block width for the mean over a contiguous last dim of d floats (vectorized: d / 4 vector lanes) at
/// `rows` outputs, 512 threads a block at most (ReduceConfig.set_block_dimension).
pub fn rmsLanes(d: usize, rows: usize) usize {
    const dim0 = d / 4;
    const d0 = if (dim0 < 512) lastPow2(dim0) else 512;
    const d1 = if (rows < 512) lastPow2(rows) else 512;
    const bw: usize = @min(d0, 32);
    const bh: usize = @min(d1, 512 / bw);
    return @min(d0, 512 / bh);
}

/// The y lanes the prompt key's packed-column pass shares: the block's x dimension must stay the norm's lane count (the
/// reduction order), so the extra lanes are whole warps over the packing loop's length D / 2 - `y` is the largest count
/// whose threads (x * y) divide that length, at most 512 threads a block and at least one. A shape whose lane count
/// does not divide D / 2 keeps y = 1 (the pass then strides, as before).
pub fn packLanes(lanes: usize, half: usize) usize {
    if (lanes == 0 or half == 0 or half % lanes != 0) return 1;
    const most = @max(1, 512 / lanes);
    var y: usize = @min(half / lanes, most);
    while (y > 1 and half % (lanes * y) != 0) y -= 1;
    return y;
}

