//! TF_DS_FUSED_TRACE (off by default): an opt-in, once-per-distinct-tuple record of which fused arm the call sites
//! select, so a run can show which kernel ran at each row count, width and PDL setting. Host-side only: the call sites
//! and launchers call the single-source `*Arm` helpers below, nothing is read back from the device, no bytes change,
//! and no fingerprint bit moves. Thread-safe and bounded: past `capacity` distinct tuples further ones are ignored.
const std = @import("std");

pub const env_name: [:0]const u8 = "TF_DS_FUSED_TRACE";

/// The arm a call site runs. `width` in the record is the shape the arm was chosen for (the compressor's channel
/// count, the indexer's column width, the rope kernel's head dim, the router's slot count), so one entry identifies
/// the exact kernel and shape.
pub const Arm = enum {
    idx_fused,
    idx_small,
    idx_unfused,
    topk_indices_cut,
    topk_indices,
    topk_indices_fast,
    cand_fast8,
    cand_fast,
    compress2x_norm,
    compress2_norm,
    compress_unfused,
    key_fused,
    key_unfused,
    latent_fused,
    latent_unfused,
    query_fused,
    query_pair,
    query_unfused,
    prompt_key_fused,
    prompt_key_unfused,
    prompt_latent_fused,
    prompt_latent_unfused,
    prune_six,
    prune_unfused,
};

pub const Entry = struct {
    arm: Arm,
    rows: usize,
    width: usize,
    pdl: bool,
};

pub const capacity = 128;

var mutex: std.atomic.Mutex = .unlocked;
var seen: [capacity]Entry = undefined;
var count: std.atomic.Value(usize) = .init(0);
// 0: uncached, 1: off, 2: on
var enabled_cache: std.atomic.Value(u8) = .init(0);

fn lock() void {
    while (!mutex.tryLock()) std.Thread.yield() catch {};
}

/// TF_DS_FUSED_TRACE: unset, "" or "0" off; anything else on.
pub fn enabled() bool {
    const cached = enabled_cache.load(.acquire);
    if (cached != 0) return cached == 2;
    lock();
    defer mutex.unlock();
    const again = enabled_cache.load(.monotonic);
    if (again != 0) return again == 2;
    const text = std.c.getenv(env_name);
    const on = if (text) |t| std.mem.span(t).len != 0 and !std.mem.eql(u8, std.mem.span(t), "0") else false;
    enabled_cache.store(if (on) 2 else 1, .release);
    return on;
}

/// Record one arm selection. Called from the call sites behind `enabled()`, and directly by the tests below.
pub fn note(arm: Arm, rows: usize, width: usize, pdl: bool) void {
    const inserted = blk: {
        lock();
        defer mutex.unlock();
        const n = count.load(.monotonic);
        for (seen[0..n]) |e| {
            if (e.arm == arm and e.rows == rows and e.width == width and e.pdl == pdl) break :blk false;
        }
        if (n >= capacity) break :blk false;
        seen[n] = .{ .arm = arm, .rows = rows, .width = width, .pdl = pdl };
        count.store(n + 1, .release);
        break :blk true;
    };
    if (inserted) {
        std.debug.print("dsv41 fused trace: {s} rows={d} width={d} pdl={d}\n", .{ @tagName(arm), rows, width, @intFromBool(pdl) });
    }
}

pub fn entries() []const Entry {
    lock();
    defer mutex.unlock();
    return seen[0..count.load(.monotonic)];
}

pub fn reset() void {
    lock();
    defer mutex.unlock();
    count.store(0, .release);
    enabled_cache.store(0, .release);
}

// -- single-source arm selection shared by the call sites and launchers ----------------------------------------------

const idx_fused = @import("idx_fused.zig");
const compress2_norm = @import("compress2_norm.zig");
const rope_store = @import("rope_store.zig");
const expert_prune = @import("expert_prune.zig");

pub const query_pair_rows: usize = 32;
pub const query_pair_warps: usize = 8;

/// The indexer's pool arm: decode (`allow_small = true`, writing `cblk`) takes `idx_small` at `rows <= small_rows` and
/// `nbk >= small_nbk`; prompt (`allow_small = false`, writing the `mask`) never takes `idx_small` because `idxPick`
/// writes only decode's block list.
pub fn idxArm(fused: bool, allow_small: bool, rows: usize, width: usize, bsize: usize, nbk: usize, k: usize) Arm {
    if (!idx_fused.fuseOk(fused, rows, width, bsize, nbk, k)) return .idx_unfused;
    return if (allow_small and rows <= idx_fused.small_rows and nbk >= idx_fused.small_nbk) .idx_small else .idx_fused;
}

/// 0254 score top-k arm (ops.zig's topkIndices): the recipe's TF_DS_TOPK_FAST keeps precedence when enabled,
/// else TF_DS_IDX_FUSED selects the early-cut radix select, else the eight-pass select runs.
pub fn topkIndicesArm(idx_fused_on: bool, topk_fast: bool) Arm {
    if (topk_fast) return .topk_indices_fast;
    return if (idx_fused_on) .topk_indices_cut else .topk_indices;
}

/// 0255 candidate-mask arm (ops.zig's candFast): vectorized eight-score loads when TF_DS_IDX_FUSED is on and every row
/// is 16-byte aligned at bsize 8, else the scalar loop.
pub fn candFastArm(idx_fused_on: bool, score: u64, stride: usize, bsize: usize) Arm {
    return if (idx_fused_on and idx_fused.candMask8Ok(score, stride, bsize)) .cand_fast8 else .cand_fast;
}

/// The compressor's arm (round.zig's decode ratio-2 chain, prompt.zig's chunk path).
pub fn compressArm(fused: bool, prompt: bool, rows: usize, d: usize) Arm {
    if (prompt) return if (compress2_norm.fuseOk(fused, rows, d)) .compress2_norm else .compress_unfused;
    return if (compress2_norm.decodeOk(fused, rows, d)) .compress2x_norm else .compress_unfused;
}

