pub fn compress2xNormPair(e: *const Exact, s: cuda.Stream, ckv: u64, ckv_ld: usize, cgate: u64, cgate_ld: usize, rslot: u64, ring_kv: u64, ring_score: u64, gi: u64, src_rows: usize, w: u64, out: u64, ldo: usize, g: usize, d: usize, eps: f32, invalid: u64) !void {
    if (g == 0) return;
    if (!compress2_pair.works(true, g, d)) return error.UnsupportedShape;
    const f = (if (d == 128) e.k_compress2x_norm128_pair else e.k_compress2x_norm512_pair) orelse return error.Compress2PairUnavailable;
    var a: cuda.Args = .{};
    a.add(ckv);
    a.add(@as(c_longlong, @intCast(ckv_ld)));
    a.add(cgate);
    a.add(@as(c_longlong, @intCast(cgate_ld)));
    a.add(rslot);
    a.add(ring_kv);
    a.add(ring_score);
    a.add(gi);
    a.add(@as(c_longlong, @intCast(src_rows)));
    a.add(w);
    a.add(out);
    a.add(@as(c_longlong, @intCast(ldo)));
    a.add(@as(c_int, @intCast(g)));
    a.add(@as(c_int, @intCast(d)));
    a.add(eps);
    a.add(invalid);
    a.add(@as(c_int, @intFromBool(e.pdl)));
    if (fused_trace.enabled()) fused_trace.note(.compress2x_pair, g, d, e.pdl);
    try cuda.launch.launch(f, .{ .grid = .{ .x = @intCast(g) }, .block = .{ .x = @intCast(d) }, .pdl = e.pdl }, s, &a);
}

